spec.expr:
label_replace(
  (
up{environment=~"prod|legacy-prod",job=~"mysql|mysql-host"}
  ),
  "role", "source", "instance", "mysql-v1[.]prod[.]zipsai[.]internal:.*"
)

label_replace(
  (
rate(
  node_disk_read_bytes_total{
    environment=~"prod|legacy-prod",
    job="mysql-host"
  }[1m]
)
and on(instance, device)
label_replace(
  node_filesystem_size_bytes{
    environment=~"prod|legacy-prod",
    job="mysql-host",
    mountpoint="/data"
  },
  "device", "$1", "device", "/dev/(.+)"
)
  ),
  "role", "source", "instance", "mysql-v1[.]prod[.]zipsai[.]internal:.*"
)

label_replace(
  (
rate(
  node_disk_written_bytes_total{
    environment=~"prod|legacy-prod",
    job="mysql-host"
  }[1m]
)
and on(instance, device)
label_replace(
  node_filesystem_size_bytes{
    environment=~"prod|legacy-prod",
    job="mysql-host",
    mountpoint="/data"
  },
  "device", "$1", "device", "/dev/(.+)"
)
  ),
  "role", "source", "instance", "mysql-v1[.]prod[.]zipsai[.]internal:.*"
)

label_replace(
  (
sum by (role, instance) (
  rate(
    node_network_receive_bytes_total{
      environment=~"prod|legacy-prod",
      job="mysql-host",
      device!~"lo|docker.*|br-.*|veth.*"
    }[1m]
  )
)
  ),
  "role", "source", "instance", "mysql-v1[.]prod[.]zipsai[.]internal:.*"
)

label_replace(
  (
sum by (role, instance) (
