    node_network_transmit_bytes_total{
      environment=~"prod|legacy-prod",
      job="mysql-host",
      device!~"lo|docker.*|br-.*|veth.*"
    }[1m]
  )
)
  ),
  "role", "source", "instance", "mysql-v1[.]prod[.]zipsai[.]internal:.*"
)

label_replace(
  (
rate(
  mysql_global_status_commands_total{
    environment=~"prod|legacy-prod",
    job="mysql",
    command=~"commit|rollback"
  }[1m]
)
  ),
  "role", "source", "instance", "mysql-v1[.]prod[.]zipsai[.]internal:.*"
)

label_replace(
  (
mysql_slave_status_slave_io_running{
  environment=~"prod|legacy-prod",
  job="mysql"
}
or
mysql_slave_status_replica_io_running{
  environment=~"prod|legacy-prod",
  job="mysql"
}
  ),
  "role", "source", "instance", "mysql-v1[.]prod[.]zipsai[.]internal:.*"
)

label_replace(
  (
mysql_slave_status_slave_sql_running{
  environment=~"prod|legacy-prod",
  job="mysql"
}
or
mysql_slave_status_replica_sql_running{
  environment=~"prod|legacy-prod",
  job="mysql"
}
  ),
  "role", "source", "instance", "mysql-v1[.]prod[.]zipsai[.]internal:.*"
)

label_replace(
  (
mysql_slave_status_last_io_errno{
  environment=~"prod|legacy-prod",
  job="mysql"
} == bool 0
  ),
  "role", "source", "instance", "mysql-v1[.]prod[.]zipsai[.]internal:.*"
)

label_replace(
  (
mysql_slave_status_last_sql_errno{
  environment=~"prod|legacy-prod",
  job="mysql"
} == bool 0
  ),
  "role", "source", "instance", "mysql-v1[.]prod[.]zipsai[.]internal:.*"
)

migration_outbox_events{
  environment="prod",
  service="migration-worker",
  status="PENDING"
}

migration_outbox_events{
  environment="prod",
  service="migration-worker",
  status="FAILED"
}

migration_outbox_oldest_pending_seconds{
  environment="prod",
  service="migration-worker"
}

sum by (direction, outcome) (
  rate(
    migration_worker_events_total{
      environment="prod",
      service="migration-worker"
    }[$__rate_interval]
  )
)

histogram_quantile(
  0.95,
  sum by (le, direction) (
    rate(
      migration_apply_lag_seconds_bucket{
        environment="prod",
        service="migration-worker"
      }[$__rate_interval]
    )
  )
)

label_replace(
  (
mysql_up{environment=~"prod|legacy-prod"}
  ),
  "role", "source", "instance", "mysql-v1[.]prod[.]zipsai[.]internal:.*"
)

migration_mode{
  environment="prod",
  service="backend"
} == 1

migration_worker_mode{
  environment="prod",
  service="migration-worker"
} == 1

migration_v2_read_percent{
  environment="prod",
  service="backend"
}

migration_shadow_read_percent{
  environment="prod",
  service="backend"
}

round(
  sum by (result) (
    increase(
      migration_shadow_read_total{
        environment="prod",
        service="backend"
      }[$__range]
    )
  )
)

migration_worker_active{
  environment="prod",
  service="migration-worker"
}

(
100 *
(
  sum(
    rate(
      http_server_requests_seconds_count{
        environment="prod",
        service="backend",
        status=~"5..",
        uri!~"/api/actuator.*"
      }[$__rate_interval]
    )
  )
  or vector(0)
)
/
clamp_min(
  sum(
    rate(
      http_server_requests_seconds_count{
        environment="prod",
        service="backend",
        uri!~"/api/actuator.*"
      }[$__rate_interval]
    )
  ),
  0.001
)
)
and on ()
(max(up{environment="prod",service="backend",job="migration-application"}) == 1)

1000 *
histogram_quantile(
  0.95,
  sum by (le) (
    rate(
      http_server_requests_seconds_bucket{
        environment="prod",
        service="backend",
        uri!~"/api/actuator.*"
      }[$__rate_interval]
    )
  )
)

sum(
  rate(
    http_server_requests_seconds_count{
      environment="prod",
      service="backend",
      uri!~"/api/actuator.*"
    }[$__rate_interval]
  )
)

hikaricp_connections_active{
  environment="prod",
  service="backend"
}
or
hikaricp_connections_active{
  environment="prod",
  service="migration-worker"
}

hikaricp_connections_pending{
  environment="prod",
  service="backend"
}
or
hikaricp_connections_pending{
  environment="prod",
  service="migration-worker"
}

label_replace(
  (
100 * (
  1 -
  avg by (role, instance) (
    rate(node_cpu_seconds_total{
      environment=~"prod|legacy-prod",
      job="mysql-host",
      mode="idle"
    }[1m])
  )
)
  ),
  "role", "source", "instance", "mysql-v1[.]prod[.]zipsai[.]internal:.*"
)

